      if (name === "File") fileHandles.add(tokens[cursor + 1]?.text === "as" ? tokens[cursor + 2]!.text : name);
      if (operations.includes(name!)) readers.add(tokens[cursor + 1]?.text === "as" ? tokens[cursor + 2]!.text : name!);
    }
